// Score the lead based on available data
const lead = $input.item.json;
let score = 0;
const signals = [];

// Source scoring
const sourceScores = { 'meta_ad': 20, 'instagram_dm': 25, 'tiktok': 15, 'google_ad': 30, 'referral': 35, 'organic': 20, 'email': 15, 'event': 30 };
score += sourceScores[lead.source] || 10;
signals.push(`Source: ${lead.source} (+${sourceScores[lead.source] || 10})`);

// Intent scoring
const message = (lead.message || '').toLowerCase();
if (message.includes('prix') || message.includes('tarif') || message.includes('combien')) { score += 25; signals.push('Intent: pricing inquiry (+25)'); }
if (message.includes('reserver') || message.includes('inscription') || message.includes('essayer')) { score += 30; signals.push('Intent: booking intent (+30)'); }
if (message.includes('membership') || message.includes('abonnement') || message.includes('forfait')) { score += 35; signals.push('Intent: membership interest (+35)'); }
if (message.includes('pilates') || message.includes('reformer')) { score += 15; signals.push('Intent: pilates interest (+15)'); }
if (message.includes('evenement') || message.includes('brunch') || message.includes('soiree')) { score += 20; signals.push('Intent: event interest (+20)'); }

// Engagement scoring
if (lead.message_count > 3) { score += 15; signals.push('Engagement: multi-message (+15)'); }
if (lead.message_count > 7) { score += 10; signals.push('Engagement: highly engaged (+10)'); }

// Cap at 100
score = Math.min(score, 100);

// Qualification
let qualification = 'cold';
if (score >= 60) qualification = 'hot';
else if (score >= 35) qualification = 'warm';

// Next action
let nextAction = 'nurture';
if (qualification === 'hot') nextAction = 'offer_trial_now';
else if (qualification === 'warm') nextAction = 'educate_and_engage';

return {
  json: {
    ...lead,
    lead_score: score,
    qualification,
    scoring_signals: signals,
    next_action: nextAction,
    qualified_at: new Date().toISOString()
  }
};

